/**
 * ContractCard.jsx — One internship contract, as the manager sees it.
 *
 * Shows the offer details (position, location, work mode, period, duration, hourly rate,
 * negotiable, description, required skills), the parties (student, employer, company, signing
 * manager) and the signature state of each party with its date and time.
 * Actions: sign (inline form, only while the manager has not signed) and PDF download in French
 * or English (independent of the language of the interface).
 *
 * The PDF is generated by the backend on demand, so it always reflects the current signatures.
 *
 * Props
 *   contract  ContractResponseDto
 *   dark      boolean
 *   devMode   boolean   Dev mode: signing needs no password
 *   onSign    function  async (contract, {termsAccepted, password}) => {success, message?}
 */

import {useState} from 'react';
import {useTranslation} from 'react-i18next';
import Button from '../../styles/Button.jsx';
import Icon from '../../styles/Icon.jsx';
import {getCvDocumentsClasses, getInternshipCardClasses} from '../../styles/AppStyles.jsx';
import {getContractFile} from '../api/Api.jsx';
import {blobUrlFromFile} from '../../utils/documents.js';
import SignContractForm from './SignContractForm.jsx';

const PDF_LANGUAGES = ["FR", "EN"];

const parseSkills = (raw) =>
    (raw ?? "").split(",").map((skill) => skill.trim()).filter(Boolean);

// Saves an API file {fileName, content (Base64)} through a temporary link
function saveFile(file) {
    const url = blobUrlFromFile(file);
    const link = document.createElement("a");
    link.href = url;
    link.download = file.fileName;
    document.body.appendChild(link);
    link.click();
    link.remove();
    setTimeout(() => URL.revokeObjectURL(url), 0);
}

function ContractCard({contract, dark, devMode = false, onSign}) {
    const {t, i18n} = useTranslation();
    const s = getInternshipCardClasses(dark);
    const th = getCvDocumentsClasses(dark);

    const [signOpen, setSignOpen] = useState(false);
    const [downloading, setDownloading] = useState(null); // "FR" | "EN" | null
    const [downloadFailed, setDownloadFailed] = useState(false);

    const {internship} = contract;
    const managerSigned = Boolean(contract.managerSignedAt);
    const skills = parseSkills(internship.requiredSkills);
    const locale = i18n.resolvedLanguage?.startsWith("fr") ? "fr-CA" : "en-CA";

    const formatWhen = (raw) => {
        const date = new Date(raw);
        return Number.isNaN(date.getTime())
            ? ""
            : new Intl.DateTimeFormat(locale, {dateStyle: "long", timeStyle: "short"}).format(date);
    };

    // Same rules as InternshipCard: to be discussed / unpaid (amount 0) / amount / not specified
    const isUnpaid = !internship.compensationNegotiable
        && internship.compensationAmount != null
        && Number(internship.compensationAmount) === 0;

    let hourlyRate;
    if (internship.compensationNegotiable) hourlyRate = t("internshipCard.compensationTbd");
    else if (internship.compensationAmount == null) hourlyRate = t("managerContracts.notSpecified");
    else if (isUnpaid) hourlyRate = t("internshipCard.compensationUnpaid");
    else hourlyRate = t("internshipCard.compensationAmount", {amount: internship.compensationAmount});

    const download = async (language) => {
        setDownloading(language);
        setDownloadFailed(false);
        try {
            saveFile(await getContractFile(contract.id, language));
        } catch {
            setDownloadFailed(true);
        } finally {
            setDownloading(null);
        }
    };

    // Student, employer, then manager (the only one who can sign here)
    const signatures = [
        {key: "student", name: contract.studentName, signedAt: contract.studentSignedAt},
        {key: "employer", name: contract.employerName, signedAt: contract.employerSignedAt},
        {key: "manager", name: contract.managerName, signedAt: contract.managerSignedAt},
    ];

    const renderSignature = ({key, name, signedAt}) => {
        const signed = Boolean(signedAt);
        let label = t("managerContracts.signatures.pending");
        if (signed) {
            label = key === "manager" && name
                ? t("managerContracts.signatures.signedBy", {date: formatWhen(signedAt), name})
                : t("managerContracts.signatures.signedAt", {date: formatWhen(signedAt)});
        }

        return (
            <li key={key} className="flex flex-wrap items-center justify-between gap-2">
                <span className="text-sm font-semibold">
                    {t(`managerContracts.parties.${key}`)}
                    {name && <span className="ml-1 font-normal opacity-80">{name}</span>}
                </span>
                <span className={`${th.pillBase} ${th.statusPill(signed ? "APPROVED" : "PENDING")} gap-1`}>
                    <Icon name={signed ? "check_circle" : "schedule"} size={14}/>
                    {label}
                </span>
            </li>
        );
    };

    const partyBox = `rounded-lg p-3 ${dark ? "bg-slate-900/30" : "bg-slate-50"}`;
    const partyLabel = `text-xs font-bold uppercase tracking-wide ${dark ? "text-slate-400" : "text-gray-500"}`;
    const divider = `border-t pt-3 ${dark ? "border-slate-700" : "border-gray-100"}`;

    return (
        <article className={s.card} aria-label={internship.title}>
            {/* Title + overall status */}
            <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="min-w-0 flex-1">
                    <h3 className={`${s.title} wrap-break-word`}>{internship.title}</h3>
                    <p className={`mt-1 text-sm ${dark ? "text-slate-400" : "text-gray-500"}`}>
                        {contract.companyName}
                    </p>
                </div>
                <span
                    className={`${th.pillBase} ${th.statusPill(managerSigned ? "APPROVED" : "PENDING")} gap-2 px-3.5! py-1.5! text-sm!`}>
                    <Icon name={managerSigned ? "check_circle" : "schedule"} size={18}/>
                    {t(managerSigned ? "managerContracts.status.signed" : "managerContracts.status.toSign")}
                </span>
            </div>

            <p className={`${s.description} w-full wrap-break-word`} style={{whiteSpace: "pre-wrap"}}>
                {internship.description}
            </p>

            {skills.length > 0 && (
                <div className={`${s.skillsRow} flex flex-wrap items-center gap-1.5`}>
                    <span className="mr-1 font-semibold">{t("internshipCard.requiredSkills")}</span>
                    {skills.map((skill) => (
                        <span key={skill} className={s.skillBadge}>{skill}</span>
                    ))}
                </div>
            )}

            {/* Offer details */}
            <div className={s.detailsRow}>
                <span className={s.detailBadge}>
                    <Icon name="location_on" size={20}/>
                    {internship.location}
                </span>
                <span className={s.detailBadge}>
                    <Icon name="work" size={20}/>
                    {t(`internshipModal.workModes.${internship.workMode}`, {defaultValue: internship.workMode})}
                </span>
                <span className={s.detailBadge} title={t("managerContracts.periodTitle")}>
                    <Icon name="calendar_month" size={20}/>
                    {t("managerContracts.period", {start: internship.startDate, end: contract.internshipEndDate})}
                </span>
                <span className={s.detailBadge}>
                    <Icon name="timer" size={20}/>
                    {t("internshipCard.durationWeeks", {count: internship.durationInWeeks})}
                </span>
                <span className={s.detailBadge}>
                    <Icon name="payments" size={20}/>
                    <span className="font-medium">{t("managerContracts.hourlyRate")}</span> {hourlyRate}
                </span>
                <span className={s.detailBadge}>
                    <span className="font-medium">{t("managerContracts.negotiable")}</span>
                    {t(internship.compensationNegotiable ? "managerContracts.yes" : "managerContracts.no")}
                </span>
            </div>

            {/* Parties */}
            <div className="grid gap-3 sm:grid-cols-3">
                <div className={partyBox}>
                    <p className={partyLabel}>{t("managerContracts.parties.student")}</p>
                    <p className="flex items-center gap-1.5 font-semibold wrap-break-word">
                        <Icon name="person" size={18}/>{contract.studentName}
                    </p>
                </div>
                <div className={partyBox}>
                    <p className={partyLabel}>{t("managerContracts.parties.employer")}</p>
                    <p className="flex items-center gap-1.5 font-semibold wrap-break-word">
                        <Icon name="person" size={18}/>{contract.employerName}
                    </p>
                    <p className="flex items-center gap-1.5 text-sm wrap-break-word opacity-80">
                        <Icon name="business_center" size={16}/>{contract.companyName}
                    </p>
                </div>
                <div className={partyBox}>
                    <p className={partyLabel}>{t("managerContracts.parties.manager")}</p>
                    <p className="flex items-center gap-1.5 font-semibold wrap-break-word">
                        <Icon name="person" size={18}/>{contract.managerName ?? "—"}
                    </p>
                </div>
            </div>

            {/* Signatures */}
            <section className={`space-y-2 ${divider}`} aria-label={t("managerContracts.signatures.title")}>
                <h4 className={`text-sm font-bold uppercase tracking-wide ${dark ? "text-slate-300" : "text-gray-700"}`}>
                    {t("managerContracts.signatures.title")}
                </h4>
                <ul className="space-y-2">{signatures.map(renderSignature)}</ul>
            </section>

            {/* Sign form */}
            {!managerSigned && signOpen && (
                <SignContractForm
                    dark={dark}
                    devMode={devMode}
                    onSubmit={(payload) => onSign(contract, payload)}
                    onClose={() => setSignOpen(false)}
                />
            )}

            {/* Actions */}
            <div
                role="group"
                aria-label={t("managerContracts.download.group")}
                className={`flex flex-wrap items-center justify-end gap-2 ${divider}`}
            >
                {downloadFailed && (
                    <span className={`mr-auto text-sm ${dark ? "text-red-300" : "text-red-600"}`} role="alert">
                        {t("managerContracts.download.failed")}
                    </span>
                )}
                {PDF_LANGUAGES.map((language) => (
                    <Button
                        key={language}
                        tone="accent"
                        lockTone
                        dark={dark}
                        icon="picture_as_pdf"
                        disabled={downloading !== null}
                        onClick={() => download(language)}
                    >
                        {t(`managerContracts.download.${language.toLowerCase()}`)}
                    </Button>
                ))}
                {!managerSigned && !signOpen && (
                    <Button tone="success" lockTone dark={dark} icon="edit" onClick={() => setSignOpen(true)}>
                        {t("managerContracts.sign.open")}
                    </Button>
                )}
            </div>
        </article>
    );
}

export default ContractCard;
